from .logger import logger
from taf.internal.managedobject import ManagedObject
from taf.transport.ssh import ssh
from taf.wts.client import WTSClient
import re

csn = ssh()
wtsclient = WTSClient()


class WtsEmuKiller(object):
    @staticmethod
    def kill_program(
        target, target_port, ssh_alias, sudo=False, sudo_password=None
    ):
        """
        kill the edaemon/egate process with the given port.

        :param target: String: Target program, "edaemon" or "egate"..
        :param target_port: Int: The program port.
        :param ssh_alias: String: which connection is the target running on.
        :param sudo: Bool: whether the program run on sudo permission.
        :return: String: kill result.
        """
        get_pid_cmd = WtsEmuKiller._generate_get_pid(
            program=target, port=target_port
        )
        program_pid = csn.execute(
            command=get_pid_cmd, connection=ssh_alias
        ).strip()
        if program_pid == "":
            logger.info(
                "{} --port {} doesn't exist".format(target, target_port)
            )
            return
        kill_cmd = WtsEmuKiller._generate_kill(
            sudo=sudo, sudo_password=sudo_password, pid=program_pid
        )
        csn.execute(command=kill_cmd, connection=ssh_alias)
        csn.assert_exit_status(
            expected_exit_code=0,
            connection=ssh_alias,
            msg="Failed to kill program, please check your arguments",
        )

    @staticmethod
    def _generate_get_pid(**cmd_args):
        # TODO: replace it with 'fuser -k', with fallback to this one if psmisc
        # TODO: package is not installed ('fuser' command is not available).
        cmd_template = (
            "ps -eo pid,cmd "
            "| grep -Ge '{program}.*--port {port}' "
            "| grep -v 'grep'"
            "| awk '{{print$1}}'"
        )

        cmd = cmd_template.format(**cmd_args)
        return cmd

    @staticmethod
    def _generate_kill(sudo=False, sudo_password=None, **cmd_args):
        cmd_template = "kill -9 {pid}"
        if sudo is True or sudo == "True":
            cmd_template = "timeout 10 sudo -S " + cmd_template
            if sudo_password:
                password_temp = "echo {password} | ".format(
                    password=sudo_password
                )
                cmd_template = password_temp + cmd_template
        return cmd_template.format(**cmd_args)


class WtsEmulator(ManagedObject):
    """WtsEmulator
    Methods:
    - :meth:`attach`: executes the attach process
    - :meth:`detach`: executes the detach process
    """

    def __init__(self, egate_console, *args, **kwargs):
        super(WtsEmulator, self).__init__(**kwargs)
        self.add_prerequisite(egate_console)
        self._egate_console = egate_console

    def configure(self, file):
        """
        send cfg file command in egate console with given file name
        :param file: the name of config file.
        """
        configure_cmd = "cfg file={file}".format(file=file)
        self._egate_console.execute(configure_cmd)

    def remove_configure(self):
        """
        reset configure in egate console, equals send "re"
        """
        self._egate_console.execute("re")

    def read_egate_output(self, filter=None):
        """
        get current outputs in egate console

        :param filter: a function to filter output
        :return:
        """
        return self._egate_console.read_output(filter=filter)

    def read_egate_output_until(self, expected, timeout=None, filter=None):
        """
        get egate output until match the expected string
        or stop when reach the timeout

        :param expected: an expected string
        :param timeout: max read time.
        :param filter: a function to filter output
        :param filter: a function to filter output
        :return: string type output in egate
        """
        return self._egate_console.read_output_until(
            expected, timeout=timeout, filter=filter
        )

    def read_egate_output_until_prompt(self, timeout=None, filter=None):
        ec = self._egate_console
        return ec.read_until_prompt(timeout=timeout, filter=filter)

    def read_egate_output_until_re(self, expected, timeout=None, filter=None):
        """
        get egate output until match the expected regular expression
        or stop when reach the timeout

        :param expected: an expected regular expression
        :param timeout: max read time.
        :param filter: a function to filter output
        :return: string type output in egate
        """
        return self._egate_console.read_output_until_re(
            expected, timeout=timeout, filter=filter
        )

    def read_wtsemu_log(self, log_path, ssh_alias, expected=None, filter=None):
        """
        get contents of log file in WTSEMU.
        match expected if given, then return the content if match succeed.
        filter the result if given.

        :param log_path: full path of log file,include file name.
        :param ssh_alias: alias of connection
        :param expected: target regular expression
        :param filter: a function to filter output
        :return: content of log file
        """
        cat_cmd = self._generate_catchlog(log_path=log_path)
        log_content = csn.execute(command=cat_cmd, connection=ssh_alias)
        logger.debug("in log file:\n{}".format(log_content))
        if expected is not None:
            evaluator = re.compile(expected)
            re_result = evaluator.search(log_content)
            if re_result is None:
                raise AttributeError("can't find expected in log file")
        if filter is not None:
            log_content = filter(log_content)
        return log_content

    @staticmethod
    def _generate_catchlog(**cmd_args):
        cmd_template = "cat {log_path}"
        return cmd_template.format(**cmd_args)

    def egate_command_executor(self, wts_command_name, **kwargs):
        cmd = getattr(wtsclient, wts_command_name)(**kwargs)
        return self._egate_console.execute(cmd)
